    "supersedes": "0.2.0-proposed",
    "compatibility": "Requires approved universal DomainPack v0.3 schema; not a drop-in replacement for current pack.ts"
  },
  "fieldSources": {
    "quoted": "Value appears verbatim within the record's quoted span on its page.",
    "derived": "Computed by code from verified quoted fields with a named primitive; never emitted by the model.",
    "classified": "Model chooses from the field's enum based on quoted text; shown as a labelled, correctable choice."
  },
  "modalities": [
    "observed",
    "planned",
    "decided"
  ],
  "missingStates": [
    "field_present_but_empty",
    "not_found_in_supplied_documents",
    "not_applicable",
    "unresolved"
  ],
  "evidencePolicy": {
    "recordQuoteRequired": true,
    "pageRequired": true,
    "quotedFieldsMustAppearInRecordQuote": true,
    "imageEvidence": "region_reference_with_ocr_text (pending engine support)",
    "onVerificationFailure": "reject_record"
  },
  "constructs": {
    "measure": {
      "description": "One construct key across present levels, evaluations, goals and progress, so a series never mixes measures.",
      "requiredFields": [
        "task",
        "score_type"
      ],
      "comparedIfBothPresent": [
        "instrument",
        "administration"
      ],
      "normalize": [
        "lowercase",
        "trim_punctuation",
        "vocabulary_synonyms"
      ],
      "onPartialMatch": "possiblySame"
    }
  },
  "unclassifiedPolicy": "Unknown documents are read with the generic checklist, never forced into a type, and never counted toward requirements."
}
